const payload = $input.item.json.payload || {};
const response = $json;
const expectedCity = $input.item.json.expected_city || '';
const candidates = Array.isArray(response.candidates) ? response.candidates : [];

return [{
  json: {
    case_name: $input.item.json.case_name,
    request_payload: payload,
    next_best_action: response.next_best_action || null,
    selected_establishment_id: response.selected_establishment_id || null,
    selected_establishment_name: response.selected_establishment_name || null,
    candidates_count: candidates.length,
    candidates: candidates.map((candidate) => ({
      id: candidate.id,
      name: candidate.name,
      city: candidate.city,
      brand: candidate.brand,
      type: candidate.establishments_type,
    })),
    off_city_candidates: candidates.filter((candidate) => String(candidate.city || '').toLowerCase() !== String(expectedCity || '').toLowerCase()).map((candidate) => ({
      id: candidate.id,
      name: candidate.name,
      city: candidate.city,
    })),
    raw_response: response,
  },
}];
